{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresi, sistemin çalıştırılması ve sensör girdilerinin verilmesiyle ölçülerek doğrulanabilir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi ile 2.000 iz altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı gözlemlenebilir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Operatörün seçtiği izin detaylarını görüntüleyebilmesi, sistemin çalıştırılıp gözlemlenerek gösterilebilir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Zamanlayıcı mantığı, girdi kesilerek ve zaman geçişi beklenerek davranışsal olarak test edilebilir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Bölge ihlali senaryosu oluşturularak görsel ve sesli uyarıların tetiklenip tetiklenmediği gözlemlenebilir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj gönderimi ve iletim durumu, iki operatör arasında mesajlaşma yapılarak ve gecikme ölçülerek test edilebilir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "Test"
      ],
      "rationale": "Operatör işlemleri gerçekleştirilerek log kayıtlarının zaman damgası ve kullanıcı kimliği ile tutarlı olduğu doğrulanabilir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Birincil sunucu arızası simüle edilerek yedek sunucunun devralma süresi ve veri bütünlüğü test edilebilir."
    }
  ]
}

