{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı girişi yapılarak gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık bekleme süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışı, zamanlayıcı testleri ile sistemin çalıştırılması üzerinden doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık süre, sisteme girdi verilerek ve sonuç gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyutu ve adet sınırlarının (10 MB, 5 dosya, PDF/JPEG/PNG) sistemin kabul edip etmediği, farklı senaryolarla sisteme girdi verilerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanınca benzersiz numara üretimi ve e-posta gönderimi, sistemin çalıştırılması ve çıktıların gözlemlenmesi ile test edilebilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde kaldığı yerden devam etme işlevi, sistemin çalıştırılması ve veri bütünlüğünün gözlemlenmesi ile doğrulanabilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğu, kullanıcı arayüzü kodunun ve yapılandırmasının standartlara göre gözle denetlenerek (inceleme) doğrulanır."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanması, altyapı yapılandırma belgeleri ve sunucu konumlarının gözle denetlenerek (inceleme) doğrulanır."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz token) verildiğinde sistemin gözlemlenebilir bir davranışını (HTTP 401) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda HTTP 429 yanıtı ve Retry-After başlığının, yüksek hacimli istekler gönderilerek sistemin tepkisinin gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Belirli bir yük altında 99. yüzdelik dilim gecikme metriğinin istatistiksel olarak doğrulanması, performans testleri ve veri analizi gerektirdiğinden analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman aşımı senaryosunun tetiklenmesi ve HTTP 504 yanıtının alınması, arka uç servisin geciktirilmesi veya durdurulmasıyla sistemin çalıştırılarak gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma olmadan ve aktif istekleri düşürmeden uygulanması, canlı sistem üzerinde değişiklik yapılarak ve istek akışının kesintisiz devam etmesi gözlemlenerek test edilmelidir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin loglanıp loglanmadığı ve log kayıtlarında gerekli alanların (izleme kimliği, süre vb.) bulunup bulunmadığı, istekler gönderildikten sonra log dosyalarının incelenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin hesaplanması, uzun süreli izleme verilerinin istatistiksel analizi gerektirdiğinden analiz yöntemi ile doğrulanmalıdır."
    }
  ]
}

