      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Sistem, erişilebilirlik testleri için hazırlanmış bir test ortamında çalışmaktadır. Ekran okuyucu yazılımı ve klavye erişim araçları yüklenmiştir.",
      "test_inputs": "WCAG 2.1 AA kontrol listesi ve standart erişilebilirlik test senaryoları.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Sistem arayüzüne klavye kullanarak erişilir ve tüm etkileşimli elemanlar (butonlar, form alanları, bağlantılar) Tab tuşuyla dolaşılır.",
          "expected": "Tüm etkileşimli elemanlara klavye ile erişilebilir ve odak sırası mantıklı bir şekilde ilerler."
        },
        {
          "no": 2,
          "action": "Ekran okuyucu yazılımı ile sayfa içeriği taranır.",
          "expected": "Görsel öğeler için uygun alternatif metinler, form alanları için etiketler ve sayfa başlıkları doğru olarak okunur."
        },
        {
          "no": 3,
          "action": "Arayüzdeki metin ve arka plan renkleri kontrol edilir.",
          "expected": "Metin ve arka plan renkleri arasındaki kontrast oranı, WCAG 2.1 AA gereksinimlerini (en az 4.5:1 normal metin için) karşılar."
        }
      ]
    }
  ]
}

{
  "test_cases": [
