      "title": "Tanımlı bölgeye girişte görsel ve sesli uyarının verilmesi",
      "covers": [
        "KK-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Sistem çalışır durumdadır. En az bir tanımlı bölge yapılandırılmıştır. Bir iz nesnesi sistem tarafından takip edilmektedir.",
      "test_inputs": "Tanımlı bölge sınırları içinde hareket eden bir iz nesnesi.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Takip edilen iz nesnesi, tanımlı bölge sınırını geçerek bölge içine girmesi sağlanır.",
          "expected": "Operatör arayüzünde görsel bir uyarı (örneğin kırmızı çerçeve, ikonu) görünür."
        },
        {
          "no": 2,
          "action": "Görsel uyarının tetiklendiği an ses çıkışı gözlemlenir.",
          "expected": "Sistem tarafından tanımlı sesli uyarı sinyali duyulur."
        }
      ]
    },
    {
      "id": "TC-KK-006-01",
      "title": "Operatörler arası metin mesajının 2 saniye içinde iletilmesi ve durum bildirimi",
      "covers": [
        "KK-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "İki operatör istasyonu sistemde aktif oturumla bağlıdır. Ağ altyapısı çalışır durumdadır.",
      "test_inputs": "Operatör A'dan Operatör B'ye gönderilecek kısa metin mesajı.",
      "assumptions": "Sistem saatleri senkronize edilmiştir ve iletme süresini ölçmek için zamanlayıcı kullanılabilir.",
      "steps": [
        {
          "no": 1,
          "action": "Operatör A, Operatör B'ye bir metin mesajı gönderir ve gönderim anı not edilir.",
          "expected": "Operatör A arayüzünde mesajın gönderildiği ve iletim durumunun (örneğin 'Gönderiliyor') gösterildiği görülür."
        },
        {
          "no": 2,
          "action": "Operatör B arayüzünde mesajın gelip gelmediği ve gelen mesajın içeriği kontrol edilir.",
          "expected": "Operatör B, gönderilen metin mesajını alıcı kutusunda görür."
        },
        {
          "no": 3,
          "action": "Mesajın Operatör B'ye ulaşma süresi hesaplanır.",
          "expected": "Mesajın iletim süresi en geç 2 saniyedir."
        },
        {
          "no": 4,
          "action": "Operatör A arayüzünde mesajın iletim durumu son kontrol edilir.",
          "expected": "Mesajın başarıyla iletildiğini gösteren durum (örneğin 'İletildi', tik işareti) görüntülenir."
        }
      ]
    }
  ]
}

