{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Verify macro-averaged F1 score meets threshold",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and the held-out evaluation set is available.",
      "test_inputs": "Held-out evaluation dataset",
      "assumptions": "The evaluation script correctly calculates macro-averaged F1 score.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation script on the held-out evaluation set.",
          "expected": "The system outputs the macro-averaged F1 score."
        },
        {
          "no": 2,
          "action": "Check the reported macro-averaged F1 score.",
          "expected": "The score is 0.90 or higher."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Verify recall difference between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and the held-out evaluation set contains labeled documents in both Turkish and English.",
      "test_inputs": "Held-out evaluation dataset with language labels",
      "assumptions": "The evaluation script can compute recall per language group.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation script to compute recall for Turkish documents.",
          "expected": "The system outputs the recall score for Turkish documents."
