        {
          "no": 2,
          "action": "Run the evaluation script to compute recall for English documents.",
          "expected": "The system outputs the recall score for English documents."
        },
        {
          "no": 3,
          "action": "Calculate the absolute difference between the Turkish and English recall scores.",
          "expected": "The difference is 5 percentage points or less."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Verify recall difference boundary at 5 percentage points",
      "covers": [
        "AI-008"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "A test dataset is constructed such that the recall difference between Turkish and English documents is exactly 5 percentage points.",
      "test_inputs": "Constructed evaluation dataset with 5% recall difference",
      "assumptions": "The dataset is valid and the model produces the expected recall values for this specific test set.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation script on the constructed dataset.",
          "expected": "The system outputs recall scores for Turkish and English documents."
        },
        {
          "no": 2,
          "action": "Calculate the absolute difference between the recall scores.",
          "expected": "The difference is exactly 5 percentage points."
        },
        {
          "no": 3,
          "action": "Check if the requirement is violated.",
          "expected": "The requirement is not violated as the difference is not greater than 5 percentage points."
        }
      ]
    },
    {
      "id": "TC-4",
      "title": "Verify recall difference exceeds 5 percentage points",
      "covers": [
        "AI-008"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "A test dataset is constructed such that the recall difference between Turkish and English documents is 6 percentage points.",
      "test_inputs": "Constructed evaluation dataset with 6% recall difference",
      "assumptions": "The dataset is valid and the model produces the expected recall values for this specific test set.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation script on the constructed dataset.",
          "expected": "The system outputs recall scores for Turkish and English documents."
        },
        {
          "no": 2,
          "action": "Calculate the absolute difference between the recall scores.",
          "expected": "The difference is 6 percentage points."
        },
        {
          "no": 3,
          "action": "Check if the requirement is violated.",
          "expected": "The requirement is violated as the difference is greater than 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "İstemci başına dakikada 600 istek sınırının uygulanması",
      "covers": [
        "SW-003"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "Ağ geçidi çalışmaktadır ve test istemcisi yapılandırılmıştır.",
      "test_inputs": "Tek bir istemci kimliği ile ardışık istekler.",
      "assumptions": "İsteklerin arka uç servise ulaşma süresi ihmal edilebilir düzeydedir ve saat penceresi 60 saniyedir.",
      "steps": [
